// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(uint8 actorSeed, uint48 depositAmt, bool doWithdraw) public {
        address actor = address(uint160(uint256(keccak256(abi.encodePacked(actorSeed)))));
        vm.assume(actor != address(0));
        vm.assume(depositAmt > 0);
        vm.deal(actor, depositAmt);
        vm.prank(actor);
        c.deposit{value: depositAmt}();
        if (doWithdraw) {
            vm.prank(actor);
            c.withdrawAll();
            vm.prank(actor);
            c.withdrawAll();
        }
        assertTrue(address(c).balance >= 0);
    }
}
